import base64
from types import SimpleNamespace

# The sandbox has no network, API key or image files, so FakeOpenAI stands in for
# openai.OpenAI() and read_bytes() stands in for open(path, "rb").read().
FAKE_FILES = {"chart.png": bytes([137, 80, 78, 71, 13, 10, 26, 10]) + b"fake chart pixels"}


def read_bytes(path):
    return FAKE_FILES[path]


class _Completions:
    def __init__(self):
        self.last_request = None

    def create(self, model, messages, **kwargs):
        self.last_request = {"model": model, "messages": messages, **kwargs}
        parts = messages[-1]["content"]
        if not isinstance(parts, list):
            raise ValueError("for vision, content must be a list of parts: text + image_url")
        texts = [p["text"] for p in parts if p.get("type") == "text"]
        urls = [p["image_url"]["url"] for p in parts if p.get("type") == "image_url"]
        if not texts or not urls:
            raise ValueError("send one {'type': 'text'} part and one {'type': 'image_url'} part")
        if not (urls[0].startswith("http") or urls[0].startswith("data:image/")):
            raise ValueError("image_url.url must be an http(s) URL or a data:image/...;base64, URL")
        where = "the linked image" if urls[0].startswith("http") else "the uploaded image"
        text = f"Answer about {where}: a bar chart with three bars."
        return SimpleNamespace(choices=[SimpleNamespace(message=SimpleNamespace(role="assistant", content=text))])


class FakeOpenAI:
    def __init__(self):
        self.chat = SimpleNamespace(completions=_Completions())


def image_part(image_source):
    """Return the image_url content part for a URL or a local file (as a base64 data URL)."""
    if image_source.startswith("http"):
        url = image_source
    else:
        encoded = base64.b64encode(read_bytes(image_source)).decode("utf-8")
        url = f"data:image/png;base64,{encoded}"
    return {"type": "image_url", "image_url": {"url": url}}


def analyze_image(client, image_source, question):
    """Ask the vision model a question about an image; return the reply text."""
    response = client.chat.completions.create(
        model="gpt-4o",
        messages=[{"role": "user", "content": [
            {"type": "text", "text": question},
            image_part(image_source),
        ]}],
    )
    return response.choices[0].message.content


client = FakeOpenAI()
print(analyze_image(client, "https://example.com/chart.png", "Describe this chart"))
print(analyze_image(client, "chart.png", "Describe this chart"))
